(function ($) {
	'use strict';
	const ShahiModules = {
		init() {
			this.bindEvents();
			this.initTooltips();
		},
		bindEvents() {
			$('.shahi-module-toggle').on(
				'change',
				this.handleModuleToggle.bind(this)
			);
			$('#shahi-enable-all-modules').on(
				'click',
				this.enableAllModules.bind(this)
			);
			$('#shahi-disable-all-modules').on(
				'click',
				this.disableAllModules.bind(this)
			);
		},
		initTooltips() {
			$('.shahi-module-card').each(function () {
				const $card = $(this);
				const $toggle = $card.find('.shahi-module-toggle');
				$toggle.on('mouseenter', function () {
					const isEnabled = $(this).is(':checked');
					const tooltip = isEnabled
						? 'Disable Module'
						: 'Enable Module';
				});
			});
		},
		handleModuleToggle(e) {
			const $checkbox = $(e.currentTarget);
			const $card = $checkbox.closest('.shahi-module-card');
			const moduleKey = $checkbox.data('module-key');
			const enabled = $checkbox.is(':checked');
			$card.addClass('shahi-module-loading');
			$.ajax({
				url: shahiModulesData.ajaxUrl,
				type: 'POST',
				data: {
					action: 'shahi_toggle_module',
					nonce: shahiModulesData.toggleNonce,
					module_key: moduleKey,
					enabled,
				},
				success: (response) => {
					this.handleToggleSuccess(
						response,
						$card,
						$checkbox,
						enabled
					);
				},
				error: (xhr, status, error) => {
					this.handleToggleError(error, $card, $checkbox, enabled);
				},
				complete: () => {
					$card.removeClass('shahi-module-loading');
				},
			});
		},
		handleToggleSuccess(response, $card, $checkbox, enabled) {
			if (response.success) {
				if (enabled) {
					$card.addClass('shahi-module-active');
				} else {
					$card.removeClass('shahi-module-active');
				}
				this.updateStatistics(enabled);
				this.showNotification(response.data.message, 'success');
				this.animateCardSuccess($card);
			} else {
				$checkbox.prop('checked', !enabled);
				this.showNotification(
					response.data.message || 'Failed to toggle module.',
					'error'
				);
			}
		},
		handleToggleError(error, $card, $checkbox, enabled) {
			$checkbox.prop('checked', !enabled);
			this.showNotification(
				'An error occurred. Please try again.',
				'error'
			);
			console.error('Module toggle error:', error);
		},
		enableAllModules(e) {
			e.preventDefault();
			if (!confirm('Are you sure you want to enable all modules?')) {
				return;
			}
			const $modules = $('.shahi-module-toggle:not(:checked)');
			if ($modules.length === 0) {
				this.showNotification(
					'All modules are already enabled.',
					'info'
				);
				return;
			}
			$modules.each((index, element) => {
				setTimeout(() => {
					$(element).prop('checked', true).trigger('change');
				}, index * 200);
			});
		},
		disableAllModules(e) {
			e.preventDefault();
			if (
				!confirm(
					'Are you sure you want to disable all modules?Some features may become unavailable.'
				)
			) {
				return;
			}
			const $modules = $('.shahi-module-toggle:checked');
			if ($modules.length === 0) {
				this.showNotification(
					'All modules are already disabled.',
					'info'
				);
				return;
			}
			$modules.each((index, element) => {
				setTimeout(() => {
					$(element).prop('checked', false).trigger('change');
				}, index * 200);
			});
		},
		updateStatistics(enabled) {
			const $totalValue = $(
				'.shahi-modules-stats .shahi-stat-card:nth-child(1).shahi-stat-value'
			);
			const $activeValue = $(
				'.shahi-modules-stats .shahi-stat-card:nth-child(2).shahi-stat-value'
			);
			const $inactiveValue = $(
				'.shahi-modules-stats .shahi-stat-card:nth-child(3).shahi-stat-value'
			);
			const total = parseInt($totalValue.text());
			let active = parseInt($activeValue.text());
			let inactive = parseInt($inactiveValue.text());
			if (enabled) {
				active++;
				inactive--;
			} else {
				active--;
				inactive++;
			}
			this.animateValue($activeValue, active);
			this.animateValue($inactiveValue, inactive);
		},
		animateValue($element, newValue) {
			const currentValue = parseInt($element.text());
			$({ value: currentValue }).animate(
				{ value: newValue },
				{
					duration: 500,
					easing: 'swing',
					step() {
						$element.text(Math.ceil(this.value));
					},
					complete() {
						$element.text(newValue);
					},
				}
			);
		},
		showNotification(message, type = 'success') {
			if (typeof ShahiNotify !== 'undefined') {
				ShahiNotify.show(message, type);
				return;
			}
			const noticeClass =
				type === 'success'
					? 'notice-success'
					: type === 'error'
					? 'notice-error'
					: 'notice-info';
			const $notice = $('<div>', {
				class: `notice ${noticeClass}is-dismissible`,
				html: `<p>${message}</p>`,
			});
			$('.shahi-modules-page').prepend($notice);
			setTimeout(() => {
				$notice.fadeOut(() => $notice.remove());
			}, 5000);
		},
		animateCardSuccess($card) {
			$card.css({
				transform: 'scale(1.05)',
				transition: 'transform 0.3s cubic-bezier(0.4,0,0.2,1)',
			});
			setTimeout(() => {
				$card.css({ transform: 'scale(1)' });
			}, 300);
		},
	};
	$(document).ready(function () {
		if ($('.shahi-modules-page').length) {
			ShahiModules.init();
		}
	});
	window.ShahiModules = ShahiModules;
})(jQuery);
